11	
12	namespace andes_sim {
13	namespace {
14	
15	long now_ms() {
16	  struct timespec ts;
17	  clock_gettime(CLOCK_MONOTONIC, &ts);
18	  return ts.tv_sec * 1000L + ts.tv_nsec / 1000000L;
19	}
20	
21	// fork + (optional chdir) + (optional stdin from /dev/null) + exec.
22	// When `wait` is true (the default) waits for the child and returns its exit
23	// code, 128+signal if signalled, or -1 on failure. When `wait` is false
24	// returns the child pid immediately without waiting (caller owns the child).
25	// Backs run_inherit (build: stdin closed, chdir), exec_passthrough (run
26	// fast/cycle: stdin inherited, no chdir), and fork_background (no wait).
27	int spawn_inherit(const std::vector<std::string>& argv, const std::string& cwd,
28	                  bool stdin_from_devnull, bool wait = true) {
29	  if (argv.empty()) return -1;
30	
31	  pid_t pid = fork();
32	  if (pid < 0) return -1;
33	
34	  if (pid == 0) {  // child
35	    if (!cwd.empty() && chdir(cwd.c_str()) != 0) _exit(127);
36	    if (stdin_from_devnull) {
37	      int devnull = open("/dev/null", O_RDONLY);
38	      if (devnull >= 0) {
39	        dup2(devnull, STDIN_FILENO);
40	        if (devnull > 2) close(devnull);
41	      }
42	    }
43	    std::vector<char*> cargv;
44	    cargv.reserve(argv.size() + 1);
45	    for (const std::string& a : argv) cargv.push_back(const_cast<char*>(a.c_str()));
46	    cargv.push_back(nullptr);
47	    execvp(cargv[0], cargv.data());
48	    _exit(127);  // exec failed
49	  }
50	
51	  if (!wait) return static_cast<int>(pid);
52	  int status = 0;
53	  waitpid(pid, &status, 0);
54	  if (WIFEXITED(status)) return WEXITSTATUS(status);
55	  if (WIFSIGNALED(status)) return 128 + WTERMSIG(status);
56	  return -1;
57	}
58	
59	}  // namespace
60	
61	RunResult run_process(const std::vector<std::string>& argv, int timeout_ms) {
62	  RunResult r;
63	  if (argv.empty()) {
64	    r.spawn_failed = true;
65	    return r;
66	  }
67	
68	  int fds[2];
69	  if (pipe(fds) != 0) {
70	    r.spawn_failed = true;
71	    return r;
72	  }
73	
74	  pid_t pid = fork();
75	  if (pid < 0) {
76	    close(fds[0]);
77	    close(fds[1]);
78	    r.spawn_failed = true;
79	    return r;
80	  }
81	
82	  if (pid == 0) {  // child
83	    close(fds[0]);
84	    dup2(fds[1], STDOUT_FILENO);
85	    int devnull = open("/dev/null", O_RDWR);
86	    if (devnull >= 0) {
87	      dup2(devnull, STDIN_FILENO);
88	      dup2(devnull, STDERR_FILENO);
89	      if (devnull > 2) close(devnull);
90	    }
91	    close(fds[1]);
92	    std::vector<char*> cargv;
93	    cargv.reserve(argv.size() + 1);
94	    for (const std::string& a : argv) cargv.push_back(const_cast<char*>(a.c_str()));
95	    cargv.push_back(nullptr);
96	    execvp(cargv[0], cargv.data());
97	    _exit(127);  // exec failed
98	  }
99	
100	  // parent
101	  close(fds[1]);
102	  int rfd = fds[0];
103	  const long deadline = now_ms() + timeout_ms;
104	  char buf[4096];
105	
106	  while (true) {
107	    long remaining = deadline - now_ms();
108	    if (remaining < 0) remaining = 0;
109	    struct pollfd pfd{rfd, POLLIN, 0};
110	    int pr = poll(&pfd, 1, static_cast<int>(remaining));
111	    if (pr < 0) {
112	      if (errno == EINTR) continue;
113	      break;
114	    }
115	    if (pr == 0) {  // timed out with no data ready
116	      kill(pid, SIGKILL);
117	      r.timed_out = true;
118	      break;
119	    }
120	    if (pfd.revents & (POLLIN | POLLHUP | POLLERR)) {
121	      ssize_t n = read(rfd, buf, sizeof(buf));
122	      if (n > 0) {
123	        r.out.append(buf, static_cast<size_t>(n));
124	      } else if (n == 0) {
125	        break;  // EOF: child closed stdout
126	      } else {
127	        if (errno == EINTR) continue;
128	        break;
129	      }
130	    }
131	    if (now_ms() >= deadline) {  // chatty child kept us past the deadline
132	      kill(pid, SIGKILL);
133	      r.timed_out = true;
134	      break;
135	    }
136	  }
137	
138	  close(rfd);
139	  int status = 0;
140	  waitpid(pid, &status, 0);
141	  // rc stays -1 (the default) when timed out or abnormally terminated.
142	  if (!r.timed_out && WIFEXITED(status)) r.rc = WEXITSTATUS(status);
143	  return r;
144	}
145	
146	int run_inherit(const std::vector<std::string>& argv, const std::string& cwd) {
147	  return spawn_inherit(argv, cwd, /*stdin_from_devnull=*/true);
148	}
149	
150	int exec_passthrough(const std::vector<std::string>& argv) {
151	  return spawn_inherit(argv, /*cwd=*/"", /*stdin_from_devnull=*/false);
152	}
153	
154	int fork_background(const std::vector<std::string>& argv) {
155	  return spawn_inherit(argv, /*cwd=*/"", /*stdin_from_devnull=*/false, /*wait=*/false);
156	}
157	
158	namespace {
159	
160	// Drain everything readable on `fd` into `buf`, delivering each completed
161	// '\n'-terminated line (newline stripped) to on_line. Returns false at EOF /
162	// error so the caller stops polling that stream.
163	bool pump_stream(int fd, int stream, std::string& buf,
164	                 const std::function<void(int, std::string_view)>& on_line) {
165	  char rb[4096];
166	  const ssize_t n = read(fd, rb, sizeof rb);
167	  if (n == 0) return false;          // EOF: child closed this stream
168	  if (n < 0) return errno == EINTR;  // transient -> keep; real error -> stop
169	  buf.append(rb, static_cast<size_t>(n));
170	  size_t nl;
171	  while ((nl = buf.find('\n')) != std::string::npos) {
172	    on_line(stream, std::string_view(buf.data(), nl));
173	    buf.erase(0, nl + 1);
174	  }
175	  return true;
176	}
177	
178	}  // namespace
179	
180	int run_line_filtered(
181	    const std::vector<std::string>& argv,
182	    const std::function<void(int, std::string_view)>& on_line) {
183	  if (argv.empty()) return -1;
184	
185	  int out_fds[2], err_fds[2];
186	  if (pipe(out_fds) != 0) return -1;
187	  if (pipe(err_fds) != 0) {
188	    close(out_fds[0]);
189	    close(out_fds[1]);
190	    return -1;
191	  }
192	
193	  pid_t pid = fork();
194	  if (pid < 0) {
195	    close(out_fds[0]);
196	    close(out_fds[1]);
197	    close(err_fds[0]);
198	    close(err_fds[1]);
199	    return -1;
200	  }
201	
202	  if (pid == 0) {  // child: stdout/stderr to the pipes, stdin inherited
203	    close(out_fds[0]);
204	    close(err_fds[0]);
205	    dup2(out_fds[1], STDOUT_FILENO);
206	    dup2(err_fds[1], STDERR_FILENO);
207	    if (out_fds[1] > 2) close(out_fds[1]);
208	    if (err_fds[1] > 2) close(err_fds[1]);
209	    std::vector<char*> cargv;
210	    cargv.reserve(argv.size() + 1);
211	    for (const std::string& a : argv) cargv.push_back(const_cast<char*>(a.c_str()));
212	    cargv.push_back(nullptr);
213	    execvp(cargv[0], cargv.data());
214	    _exit(127);  // exec failed
215	  }
216	
217	  // parent: poll both pipes, line-buffer each, until both hit EOF. No timeout --
218	  // matches exec_passthrough (a cycle run can be arbitrarily long).
219	  close(out_fds[1]);
220	  close(err_fds[1]);
221	  int fd[2] = {out_fds[0], err_fds[0]};
222	  const int stream[2] = {1, 2};
223	  std::string buf[2];
224	  bool open_[2] = {true, true};
225	
226	  while (open_[0] || open_[1]) {
227	    struct pollfd pfd[2];
228	    int idx[2];
229	    int n = 0;
230	    for (int i = 0; i < 2; ++i)
231	      if (open_[i]) {
232	        pfd[n] = {fd[i], POLLIN, 0};
233	        idx[n] = i;
234	        ++n;
235	      }
236	    if (poll(pfd, n, -1) < 0) {
237	      if (errno == EINTR) continue;
238	      break;
239	    }
240	    for (int k = 0; k < n; ++k) {
241	      const int i = idx[k];
242	      if (pfd[k].revents & (POLLIN | POLLHUP | POLLERR))
243	        if (!pump_stream(fd[i], stream[i], buf[i], on_line)) open_[i] = false;
244	    }
245	  }
246	  // Flush any final line that arrived without a trailing newline.
247	  for (int i = 0; i < 2; ++i)
248	    if (!buf[i].empty()) on_line(stream[i], buf[i]);
249	
250	  close(fd[0]);
251	  close(fd[1]);
252	  int status = 0;
253	  waitpid(pid, &status, 0);
254	  if (WIFEXITED(status)) return WEXITSTATUS(status);
255	  if (WIFSIGNALED(status)) return 128 + WTERMSIG(status);
256	  return -1;
257	}
258	
259	}  // namespace andes_sim
