199	PlanResult run_plan(const Plan& plan,
200	                    const std::vector<EngineDescriptor>& engines,
201	                    const PlanOptions& opts) {
202	  PlanResult res;
203	  if (plan.steps.empty()) {
204	    res.error = "plan has no steps";
205	    return res;
206	  }
207	
208	  // Acquire the shared mmap: allocate one (and own it) when none is pinned.
209	  std::string mmap_path = plan.mmap_path;
210	  const bool own_mmap = mmap_path.empty();
211	  if (own_mmap) {
212	    std::string err;
213	    // L26/F2: back the mmap with one V-scratch page above the program's RAM.
214	    mmap_path = allocate(physical_mmap_bytes(plan.mem_size), err);
215	    if (mmap_path.empty()) {
216	      res.error = err;
217	      return res;
218	    }
219	  }
220	
221	  // A private dir for the threaded drain files.
222	  std::error_code ec;
223	  fs::path workdir = fs::temp_directory_path(ec) / "andesim-plan-XXXXXX";
224	  std::string tmpl = workdir.string();
225	  std::vector<char> tbuf(tmpl.begin(), tmpl.end());
226	  tbuf.push_back('\0');
227	  const char* made = ::mkdtemp(tbuf.data());
228	  if (!made) {
229	    if (own_mmap) ::unlink(mmap_path.c_str());
230	    res.error = "failed to create plan work dir";
231	    return res;
232	  }
233	  const std::string wd = made;
234	
235	  RuntimeCtx ctx;
236	  ctx.mmap_path = mmap_path;
237	  // L26/F2: the legs (QEMU backend size, vsim --shared-mem-size) see the
238	  // PHYSICAL window -- program RAM plus the V-scratch page. The program's own
239	  // linker script still uses only --mem-size, so the scratch page sits above
240	  // everything it can address.
241	  ctx.mem_size = physical_mmap_bytes(plan.mem_size);
242	  ctx.plugin_path = resolve_plugin(opts.plugin_path);  // mmap_base keeps its "0x0" default
243	
244	  // Match the QEMU producer leg's ISA to the accurate engine: ask that engine
245	  // for a QEMU -readconfig cfg distilled from its config.inc. Tolerant -- an
246	  // engine without --print-qemu-config leaves qemu_cfg empty (the parser throws
247	  // on the unknown flag -> non-zero exit), so the fast leg keeps its -cpu.
248	  for (const Step& s : plan.steps)
249	    if (s.role == "accurate-leg")
250	      if (const EngineDescriptor* e = find_engine(engines, s.engine_id);
251	          e && !e->bin_path.empty()) {
252	        ctx.qemu_cfg = stage_qemu_cfg(
253	            wd, run_process({e->bin_path, "--print-qemu-config"}, kQemuCfgProbeMs));
254	        break;
255	      }
256	
257	  std::string err;
258	  const std::vector<std::vector<std::string>> argvs =
259	      plan_argvs(plan, engines, wd, ctx, err);
260	  if (!err.empty()) {
261	    res.error = err;
262	  } else if (opts.dry_run) {
263	    // Build-only: the argvs are fully resolved (placeholders, staged qemu_cfg,
264	    // threaded state paths) -- record them for the caller to print, spawn none.
265	    res.argvs = argvs;
266	  } else {
267	    res.argvs = argvs;
268	    for (size_t i = 0; i < argvs.size(); ++i) {
269	      const RunResult r = run_process(argvs[i], opts.timeout_ms);
270	      if (r.spawn_failed) {
271	        res.error = "plan step " + std::to_string(i) + ": failed to spawn";
272	        break;
273	      }
274	      if (r.timed_out) {
275	        res.error = "plan step " + std::to_string(i) + ": timed out after " +
276	                    std::to_string(opts.timeout_ms) + " ms";
277	        break;
278	      }
279	      if (r.rc != opts.expect_rc) {
280	        res.error = plan_step_rc_error(i, plan.steps[i], opts.expect_rc, r.rc);
281	        break;
282	      }
283	      const StateFile sf = read_state_file(state_path(wd, i));
284	      if (!sf.ok()) {
285	        res.error = "plan step " + std::to_string(i) + ": " + sf.error;
286	        break;
287	      }
288	      res.phases.push_back({sf.st.mcycle, sf.st.minstret, r.out, sf.st});
289	    }
290	  }
291	
292	  fs::remove_all(wd, ec);
293	  if (own_mmap) ::unlink(mmap_path.c_str());
294	  return res;
295	}
296	
297	}  // namespace andes_sim
